-- ACB daily price history (seed for a fresh database).
-- Runs once via /docker-entrypoint-initdb.d when the Postgres data volume is empty.
--
-- Generated from the repaired acb_stock table. To refresh it later:
--   python3 scripts/backfill_acb.py --start <date>     # update the live table
--   then regenerate this file with the same COPY export.
--
-- Units: prices in VND, volume in millions of shares, change in % vs previous close.

DROP TABLE IF EXISTS acb_stock;

CREATE TABLE acb_stock (
    date   DATE PRIMARY KEY,
    close  DOUBLE PRECISION,
    open   DOUBLE PRECISION,
    high   DOUBLE PRECISION,
    low    DOUBLE PRECISION,
    volume DOUBLE PRECISION,
    change DOUBLE PRECISION
);

